<template><section class="page"><header class="hero"><div><span>EXPERIMENT & CONTRACT LAB</span><h1>Prompt / Tool 实验治理</h1><p>稳定分流、真实结果归因、胜出发布；输入 Contract 版本、样例回归与运行观测。</p></div><el-button color="#e8a23d" @click="load">刷新数据</el-button></header><el-tabs v-model="tab" class="panel">
<el-tab-pane label="Prompt 实验" name="prompt"><div class="toolbar"><el-button type="primary" @click="openExperiment()">新增实验</el-button></div><el-table :data="experiments" border><el-table-column prop="experiment_code" label="编码" min-width="150"/><el-table-column prop="experiment_name" label="名称" min-width="160"/><el-table-column prop="stage" label="阶段" width="100"/><el-table-column prop="allocation_key" label="稳定分流" width="110"/><el-table-column label="Variants" min-width="260"><template #default="{row}"><el-tag v-for="v in variants(row)" :key="v.variantCode" class="tag">{{v.variantCode}} P{{v.promptId}} / {{v.weight}}</el-tag></template></el-table-column><el-table-column prop="status" label="状态" width="100"/><el-table-column label="操作" width="190"><template #default="{row}"><el-button link @click="openExperiment(row)">编辑</el-button><el-button v-if="row.status==='running'" link type="success" @click="openWinner(row)">发布胜出</el-button></template></el-table-column></el-table><h3>真实运行指标</h3><el-table :data="experimentMetrics" border><el-table-column prop="experiment_code" label="实验"/><el-table-column prop="variant_code" label="Variant"/><el-table-column prop="exposures" label="曝光"/><el-table-column prop="success_rate" label="成功率 %"/><el-table-column prop="avg_duration_ms" label="平均耗时 ms"/><el-table-column prop="total_cost" label="总成本"/></el-table></el-tab-pane>
<el-tab-pane label="Tool Contract" name="contract"><div class="toolbar"><el-select v-model="selectedToolId" filterable placeholder="选择 Tool" @change="loadContracts"><el-option v-for="t in tools" :key="t.toolId" :label="`${t.toolName} (${t.toolCode})`" :value="t.toolId"/></el-select><el-button :disabled="!selectedToolId" type="primary" @click="contractVisible=true">新增 Contract</el-button></div><el-table :data="contracts" border><el-table-column prop="contract_version" label="版本"/><el-table-column prop="max_payload_chars" label="最大字符"/><el-table-column prop="compatibility" label="兼容性"/><el-table-column prop="test_case_count" label="用例数"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="220"><template #default="{row}"><el-button link @click="openCase(row)">加用例</el-button><el-button v-if="row.status==='draft'" link type="success" @click="publish(row)">回归并发布</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="Tool 输入观测" name="observation"><div class="cards"><article v-for="m in toolMetrics" :key="m.tool_code"><b>{{m.tool_code}}</b><span>{{m.calls}} calls</span><span>失败 {{m.failure_rate}}%</span><span>裁剪 {{m.clamped_count}}</span></article></div><el-table :data="observations" border><el-table-column prop="observed_at" label="时间" min-width="170"/><el-table-column prop="tool_code" label="Tool"/><el-table-column prop="contract_version" label="Contract"/><el-table-column prop="raw_input_chars" label="原始字符"/><el-table-column prop="final_input_chars" label="最终字符"/><el-table-column prop="schema_valid" label="Schema"/><el-table-column prop="clamped" label="裁剪"/><el-table-column prop="status" label="状态"/><el-table-column prop="error_code" label="错误" min-width="170"/></el-table></el-tab-pane></el-tabs>
<el-dialog v-model="experimentVisible" title="Prompt 实验" width="760"><el-form label-width="130"><el-form-item label="编码 / 名称"><el-input v-model="experimentForm.experimentCode" :disabled="!!experimentForm.id" style="width:45%"/><el-input v-model="experimentForm.experimentName" style="width:52%;margin-left:3%"/></el-form-item><el-form-item label="基础 Prompt"><el-select v-model="experimentForm.basePromptId" filterable><el-option v-for="p in prompts" :key="p.promptId" :label="p.promptName" :value="p.promptId"/></el-select></el-form-item><el-form-item label="阶段 / 分流键"><el-select v-model="experimentForm.stage"><el-option value="system"/><el-option value="decision"/><el-option value="planner"/></el-select><el-select v-model="experimentForm.allocationKey" style="margin-left:12px"><el-option value="conversation"/><el-option value="user"/></el-select></el-form-item><el-form-item label="覆盖 / 状态"><el-input-number v-model="experimentForm.rolloutPercent" :min="1" :max="100"/>%<el-select v-model="experimentForm.status" style="margin-left:15px"><el-option value="draft"/><el-option value="running"/><el-option value="paused"/><el-option value="cancelled"/></el-select></el-form-item><el-divider>Variants</el-divider><div v-for="(v,i) in experimentForm.variants" :key="i" class="variant"><el-input v-model="v.variantCode" placeholder="code"/><el-input v-model="v.variantName" placeholder="name"/><el-select v-model="v.promptId" filterable><el-option v-for="p in prompts" :key="p.promptId" :label="p.promptName" :value="p.promptId"/></el-select><el-input-number v-model="v.weight" :min="1"/><el-checkbox v-model="v.control">control</el-checkbox></div></el-form><template #footer><el-button @click="experimentVisible=false">取消</el-button><el-button type="primary" @click="saveExp">保存</el-button></template></el-dialog>
<el-dialog v-model="contractVisible" title="新增 Tool Contract" width="680"><el-form label-width="130"><el-form-item label="版本"><el-input v-model="contractForm.contractVersion"/></el-form-item><el-form-item label="Input Schema"><el-input v-model="contractForm.schemaText" type="textarea" :rows="8"/></el-form-item><el-form-item label="最大字符"><el-input-number v-model="contractForm.maxPayloadChars" :min="1"/></el-form-item><el-form-item label="敏感路径"><el-select v-model="contractForm.sensitivePaths" multiple allow-create filterable style="width:100%"/></el-form-item><el-form-item label="兼容性"><el-select v-model="contractForm.compatibility"><el-option value="compatible"/><el-option value="breaking"/><el-option value="unknown"/></el-select></el-form-item></el-form><template #footer><el-button @click="contractVisible=false">取消</el-button><el-button type="primary" @click="saveContract">保存 Draft</el-button></template></el-dialog>
<el-dialog v-model="caseVisible" title="新增 Contract 回归用例" width="620"><el-form label-width="120"><el-form-item label="用例名称"><el-input v-model="caseForm.caseName"/></el-form-item><el-form-item label="输入 JSON"><el-input v-model="caseForm.payloadText" type="textarea" :rows="7"/></el-form-item><el-form-item label="预期合法"><el-switch v-model="caseForm.expectedValid"/></el-form-item></el-form><template #footer><el-button @click="caseVisible=false">取消</el-button><el-button type="primary" @click="saveCase">保存</el-button></template></el-dialog></section></template>
<script setup lang="ts">import{onMounted,reactive,ref}from"vue";import{ElMessage,ElMessageBox}from"element-plus";import{fetchPromptPage}from"@/api/prompt";import{fetchToolPage}from"@/api/tool";import{addContractCase,completeExperiment,createToolContract,fetchExperimentMetrics,fetchExperiments,fetchToolContracts,fetchToolInputMetrics,fetchToolInputObservations,publishContract,saveExperiment}from"@/api/experimentGovernance";const tab=ref("prompt"),experiments=ref<any[]>([]),experimentMetrics=ref<any[]>([]),prompts=ref<any[]>([]),tools=ref<any[]>([]),selectedToolId=ref<number|null>(null),contracts=ref<any[]>([]),toolMetrics=ref<any[]>([]),observations=ref<any[]>([]),experimentVisible=ref(false),contractVisible=ref(false),caseVisible=ref(false),selectedContract=ref<any>(null);const experimentForm=reactive<any>({}),contractForm=reactive({contractVersion:"1.0.0",schemaText:'{"type":"object","properties":{},"required":[]}',maxPayloadChars:20000,sensitivePaths:[]as string[],compatibility:"compatible"}),caseForm=reactive({caseName:"",payloadText:"{}",expectedValid:true});function variants(r:any){return typeof r.variants==='string'?JSON.parse(r.variants):r.variants||[]}async function load(){[experiments.value,experimentMetrics.value,toolMetrics.value,observations.value]=await Promise.all([fetchExperiments(),fetchExperimentMetrics(),fetchToolInputMetrics(),fetchToolInputObservations()]);const[p,t]=await Promise.all([fetchPromptPage({pageNum:1,pageSize:500}),fetchToolPage({pageNum:1,pageSize:500})]);prompts.value=p.records;tools.value=t.records}function openExperiment(r?:any){Object.assign(experimentForm,r?{id:r.id,experimentCode:r.experiment_code,experimentName:r.experiment_name,basePromptId:r.base_prompt_id,agentId:r.agent_id,stage:r.stage,allocationKey:r.allocation_key,rolloutPercent:r.rollout_percent,status:r.status,variants:variants(r).map((v:any)=>({...v,status:v.status||"enabled"}))}:{id:null,experimentCode:"",experimentName:"",basePromptId:null,agentId:null,stage:"system",allocationKey:"conversation",rolloutPercent:100,status:"draft",variants:[{variantCode:"control",variantName:"Control",promptId:null,weight:50,control:true,status:"enabled"},{variantCode:"candidate",variantName:"Candidate",promptId:null,weight:50,control:false,status:"enabled"}]});experimentVisible.value=true}async function saveExp(){const{id,...p}=experimentForm;await saveExperiment(id,p);experimentVisible.value=false;ElMessage.success("实验已保存");await load()}async function openWinner(r:any){const list=variants(r);const labels=list.map((v:any)=>`${v.promptId}: ${v.variantName}`).join("\n");const{value}=await ElMessageBox.prompt(`输入胜出 Prompt ID：\n${labels}`,"发布胜出版本");await completeExperiment(r.id,Number(value));ElMessage.success("胜出 Prompt 已发布");await load()}async function loadContracts(){contracts.value=selectedToolId.value?await fetchToolContracts(selectedToolId.value):[]}async function saveContract(){if(!selectedToolId.value)return;await createToolContract(selectedToolId.value,{contractVersion:contractForm.contractVersion,inputSchema:JSON.parse(contractForm.schemaText),maxPayloadChars:contractForm.maxPayloadChars,sensitivePaths:contractForm.sensitivePaths,compatibility:contractForm.compatibility,status:"draft",releaseNotes:""});contractVisible.value=false;await loadContracts()}function openCase(r:any){selectedContract.value=r;Object.assign(caseForm,{caseName:"",payloadText:"{}",expectedValid:true});caseVisible.value=true}async function saveCase(){await addContractCase(selectedContract.value.id,{caseName:caseForm.caseName,inputPayload:JSON.parse(caseForm.payloadText),expectedValid:caseForm.expectedValid,errorContains:null,status:"enabled"});caseVisible.value=false;await loadContracts()}async function publish(r:any){const result=await publishContract(r.id);ElMessage.success(`回归通过，共 ${result.caseCount} 个用例`);await loadContracts()}onMounted(load);</script>
<style scoped>.page{min-width:0}.hero{display:flex;justify-content:space-between;align-items:end;padding:30px;color:#fff7e8;background:linear-gradient(125deg,#172431,#24434a 60%,#80572d);border-radius:20px 20px 0 0}.hero span{font:600 11px Georgia;letter-spacing:.2em;color:#e8a23d}.hero h1{margin:8px 0;font:700 32px Georgia}.hero p{margin:0;color:#c6d4d2}.panel{padding:18px 20px;background:white;border-radius:0 0 20px 20px}.toolbar{display:flex;gap:12px;margin-bottom:14px}.toolbar .el-select{width:340px}.tag{margin:2px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.cards article{display:flex;flex-direction:column;gap:6px;padding:16px;border:1px solid #d6e0de;border-radius:12px}.variant{display:grid;grid-template-columns:1fr 1fr 1.5fr 120px 90px;gap:8px;margin:8px 0}@media(max-width:1000px){.cards{grid-template-columns:1fr 1fr}.variant{grid-template-columns:1fr}}</style>
